[{"order":1,"type":"heading","text":"Advanced Next.js Routing: Parallel Routes and Intercepting Routes"},{"order":2,"type":"paragraph","text":"Next.js provides powerful advanced routing mechanisms that allow developers to build complex user interfaces. Two of the most sophisticated features are Parallel Routes and Intercepting Routes. Combined, they enable patterns like modal dialogs that maintain their own URLs, split-pane views, and conditionally rendered layouts."},{"order":3,"type":"subheading","text":"Understanding Parallel Routes"},{"order":4,"type":"paragraph","text":"Parallel Routes allow you to simultaneously or conditionally render multiple pages within the same layout. They are defined using a convention known as slots. A slot is created using the @folder syntax. Slots are passed as props to the shared parent layout."},{"order":5,"type":"bullet_point","text":"Slots do not affect the URL structure; @folder/page maps directly to the parent route."},{"order":6,"type":"bullet_point","text":"They allow independent navigation within each slot, meaning the user can change tabs or pagination in one pane without affecting the other."},{"order":7,"type":"bullet_point","text":"Next.js automatically handles default.js files as fallback states when a slot's active state cannot be determined during a hard refresh."},{"order":8,"type":"subheading","text":"Project Structure for Parallel Routes"},{"order":9,"type":"code","text":"app/
├── layout.js
├── page.js
├── @analytics/
│   └── page.js
└── @team/
    └── page.js"},{"order":10,"type":"subheading","text":"Consuming Parallel Routes in Layout"},{"order":11,"type":"code","text":"export default function Layout({ children, analytics, team }) {
  return (
    <div className="dashboard">
      <div className="main">{children}</div>
      <div className="sidebar">
        {analytics}
        {team}
      </div>
    </div>
  );
}"},{"order":12,"type":"subheading","text":"Understanding Intercepting Routes"},{"order":13,"type":"paragraph","text":"Intercepting routes allow you to load a route from another part of your application within the current layout. This is particularly useful when you want to show context, such as opening a photo in a modal while keeping the background context of the photo feed intact."},{"order":14,"type":"bullet_point","text":"(.) matches routes on the same level."},{"order":15,"type":"bullet_point","text":"(..) matches routes one level above."},{"order":16,"type":"bullet_point","text":"(..)(..) matches routes two levels above."},{"order":17,"type":"bullet_point","text":"(...) matches routes from the root app directory."},{"order":18,"type":"subheading","text":"Combining Parallel and Intercepting Routes for Modals"},{"order":19,"type":"paragraph","text":"The classic use case for combining these two features is a photo gallery where clicking a photo opens a modal overlay. If the user refreshes the page or shares the URL directly, the photo renders as a full page instead of a modal."},{"order":20,"type":"code","text":"app/
├── feed/
│   ├── page.js
│   └── layout.js
│   └── @modal/
│       └── (.)photo/[id]/page.js
└── photo/
    └── [id]
        └── page.js"},{"order":21,"type":"subheading","text":"Implementing the Modal Layout"},{"order":22,"type":"code","text":"export default function FeedLayout({ children, modal }) {
  return (
    <div>
      {children}
      {modal}
    </div>
  );
}"},{"order":23,"type":"subheading","text":"Building the Intercepted Modal Component"},{"order":24,"type":"code","text":"import { Modal } from '@/components/modal';

export default function PhotoModal({ params: { id } }) {
  return (
    <Modal>
      <div className="p-4">
        <h2>Photo ID: {id}</h2>
        <img src={`/images/${id}.jpg`} alt="Intercepted Photo" />
      </div>
    </Modal>
  );
}"},{"order":25,"type":"subheading","text":"Conclusion"},{"order":26,"type":"paragraph","text":"By mastering Parallel and Intercepting Routes in Next.js, you can build rich, Single Page Application (SPA)-like experiences while maintaining full Server-Side Rendering (SSR) capability, robust SEO performance, and correct URL sharing behavior."}]
